/* ===================== MOVEMENT ANALYSIS CAPSTONE: PUTTING IT ALL TOGETHER =====================
   Tabs: four-step framework & hierarchical-model builder · inverted U · standing balance · jump & landing · cycling · drinking from
   a glass · wheelchair push · gait viewer · final review (cross-course drill) · problems.
   Source: ME 320 Lectures 15–16 (Dr. Walck); gait shapes after Winter / Novacheck 1998 (synthetic curves, labelled as such) plus one measured stride from the OpenSim Rajagopal example data (gait_data.js).   */
const CP=(()=>{
  const $=(s)=>document.querySelector(s); const f=(x,d=2)=>isFinite(x)?(+x).toFixed(d):"—"; const rad=(d)=>d*Math.PI/180, deg=(r)=>r*180/Math.PI; const g=9.81;
  let svgN=0; const svg=(w,h,inner,cls="")=>{ const uid="c"+(svgN++); return `<svg viewBox="0 0 ${w} ${h}" class="mlsvg ${cls}" preserveAspectRatio="xMidYMid meet">${inner.split("@@").join(uid)}</svg>`; };
  const MK={"#7cff6b":"ahg","#22d3ee":"ahc","#ffd23f":"ahy","#ff8a3d":"aho","#ff5a5a":"ahr","#b58cff":"ahp"};
  const ARROW=`<defs>${Object.entries(MK).map(([c,id])=>`<marker id="${id}@@" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${c}"/></marker>`).join("")}</defs>`;
  const arrow=(x1,y1,x2,y2,col,w=3)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" marker-end="url(#${MK[col]||"ahc"}@@)"/>`;
  const txt=(x,y,s,o="")=>`<text x="${x}" y="${y}" class="mlab" ${o}>${s}</text>`;
  const pick=(a)=>a[Math.floor(Math.random()*a.length)]; const shuffle=(a)=>a.map(x=>[Math.random(),x]).sort((p,q)=>p[0]-q[0]).map(p=>p[1]);

  /* ---------- 1. framework & hierarchical model builder ---------- */
  const TASKS={
    vjump:{n:"Vertical jump",obj:"Maximise the height of the COM at the apex",corr:[{t:"COM height at take-off",c:true,kids:["Standing height","Full extension of hip, knee, ankle at take-off","Arm position at take-off"]},{t:"Vertical velocity at take-off",c:true,kids:["Net vertical impulse ∫(GRF − W)dt","Body mass","Countermovement depth and speed","Rate of force development","Proximal-to-distal sequencing"]}],uncontrollable:["Standing height","Body mass"],model:"impulse–momentum or work–energy",cls:"discrete",phases:"Preparation (countermovement: hips/knees flex, ankles dorsiflex) → Propulsion (COM lowest → take-off) → Braking (landing)",principles:"use the SSC; sequence proximal-to-distal; maximise the distance/time over which force acts"},
    ljump:{n:"Long jump",obj:"Maximise horizontal distance of the COM flight",corr:[{t:"Take-off velocity (squared!)",c:true,kids:["Approach run speed","Vertical impulse at the board","Conversion of horizontal to vertical velocity"]},{t:"Take-off angle",c:true,kids:["Penultimate-step lowering","Board contact time"]},{t:"Take-off and landing heights",c:true,kids:["Standing height","Landing position (legs forward)"]}],uncontrollable:["Standing height"],model:"projectile: R = v² sin 2θ / g (+ height terms)",cls:"discrete (a vertical jump rotated before extension)",phases:"Approach → take-off (propulsion) → flight → landing (braking)",principles:"velocity matters more than angle (it is squared); minimise external torque at the board"},
    walk:{n:"Walking",obj:"No single mechanical objective — move the COM forward economically at a chosen speed without falling",corr:[{t:"Step length × cadence = speed",c:true,kids:["Hip range of motion","Push-off impulse (plantar flexors)","Leg length"]},{t:"Metabolic cost per metre",c:true,kids:["Vertical COM excursion","Energy absorbed at each heel strike","Soft-tissue dissipation"]},{t:"Stability margin",c:true,kids:["Step width","Reaction time to perturbation"]}],uncontrollable:["Leg length"],model:"hierarchical model required — no single equation",cls:"cyclic",phases:"Stance (propulsion and support) → swing (recovery), alternating legs",principles:"cross out what you cannot change; find the limiting factor before strengthening anything"},
    glass:{n:"Drinking from a glass (stroke patient)",obj:"Grasp the glass and transport it to the mouth without slipping or tipping",corr:[{t:"Static grip force (friction ≥ weight)",c:true,kids:["Grip strength","Friction coefficient of glass","Glass mass"]},{t:"Static torque balance (no tipping)",c:true,kids:["Grip location relative to COM","Glass height / width"]},{t:"Reach and transport kinematics",c:true,kids:["Elbow and shoulder ROM","Trunk compensation","Hand steadiness"]}],uncontrollable:["Friction coefficient of glass"],model:"statics: ΣF = 0 (11 forces), ΣM_COM = 0 (10 torques)",cls:"serial (reach & grasp → transport → drink → return)",phases:"Reach & grasp (extension) → forward transport (flexion) → drinking → backward transport (extension) → return",principles:"improve the impaired DOF, or the capacity of the DOFs that substitute for it; or change the task (lighter, smaller glass)"}};
  let hm={task:"vjump",crossed:{},mode:"view",quiz:null};
  function renderHM(){ const el=$("#frame"); const T=TASKS[hm.task]; const boxW=150;
    const nodes=[]; let x=40; T.corr.forEach((c,i)=>{ const kids=c.kids; const w=Math.max(boxW,kids.length*110); nodes.push({c,x,w,kids}); x+=w+20; }); const totalW=x; const sc=Math.min(1,560/totalW);
    const tree=svg(600,260,ARROW+`<g transform="scale(${sc}) translate(${(600/sc-totalW)/2},0)"><rect x="${totalW/2-170}" y="10" width="340" height="40" rx="8" fill="#ffd23f" fill-opacity=".9"/>`+txt(totalW/2,35,T.obj.length>60?T.obj.slice(0,58)+"…":T.obj,'text-anchor="middle" style="fill:#1a0a00;font-size:11px"')
      +nodes.map(n=>`<line x1="${totalW/2}" y1="50" x2="${n.x+n.w/2}" y2="90" stroke="#2c4274" stroke-width="2"/><rect x="${n.x+n.w/2-70}" y="90" width="140" height="40" rx="8" fill="#22d3ee" fill-opacity=".85"/>`+txt(n.x+n.w/2,114,n.c.t.length>26?n.c.t.slice(0,25)+"…":n.c.t,'text-anchor="middle" style="fill:#031218;font-size:10px"')
        +n.kids.map((k,j)=>{ const kx=n.x+(j+0.5)*(n.w/n.kids.length); const off=!!hm.crossed[k]; return `<line x1="${n.x+n.w/2}" y1="130" x2="${kx}" y2="180" stroke="#2c4274" stroke-width="1.5"/><rect x="${kx-54}" y="180" width="108" height="60" rx="8" fill="${off?"#2c4274":"#b58cff"}" fill-opacity=".85" data-k="${k}" style="cursor:pointer"/>`+txt(kx,202,k.length>17?k.slice(0,17):k,`text-anchor="middle" style="fill:${off?"#8ea3cf":"#0b0320"};font-size:9px;pointer-events:none"`)+(k.length>17?txt(kx,214,k.slice(17,34),`text-anchor="middle" style="fill:${off?"#8ea3cf":"#0b0320"};font-size:9px;pointer-events:none"`):"")+(k.length>34?txt(kx,226,k.slice(34,51),`text-anchor="middle" style="fill:${off?"#8ea3cf":"#0b0320"};font-size:9px;pointer-events:none"`):"")+(off?`<line x1="${kx-46}" y1="186" x2="${kx+46}" y2="234" stroke="#ff5a5a" stroke-width="3" style="pointer-events:none"/>`:""); }).join("")).join("")+`</g>`+txt(300,252,"click a factor box to cross it out (uncontrollable) · objective → correlates → factors",'text-anchor="middle" class="mlab dim"'));
    const allKids=T.corr.flatMap(c=>c.kids); const right=allKids.filter(k=>(T.uncontrollable.includes(k))===!!hm.crossed[k]).length;
    el.innerHTML=`<div class="hierbar">${Object.keys(TASKS).map(k=>`<button type="button" class="tabbtn ${k===hm.task?"on":""}" data-task="${k}">${TASKS[k].n}</button>`).join("")}</div>
      <div class="cols"><div class="box"><h3>1 · Objective</h3><p>${T.obj}</p><p class="note">State it as something to maximise or minimise — a clear optimisation criterion.</p></div><div class="box"><h3>2 · Mechanical correlates</h3><ul class="plain">${T.corr.map(c=>`<li>${c.t}</li>`).join("")}</ul><p class="note">Model: ${T.model}</p></div><div class="box"><h3>3 · Movement solution</h3><p><b>Class:</b> ${T.cls}.<br><b>Phases:</b> ${T.phases}</p><p class="note"><b>Guiding principles:</b> ${T.principles}.</p></div><div class="box"><h3>4 · Cause & intervention</h3><p class="note">Beyond biomechanics: needs exercise science and psychology. Three constraint types shape what is possible — <b>organismic</b> (ROM, strength, power, endurance of each DOF), <b>environmental</b>, <b>task</b>.</p></div></div>
      <h4 style="margin:14px 0 6px">Hierarchical model — cross out what cannot be changed</h4>${tree}
      <div class="ro"><span>Crossing-out check: factors correctly classified</span><b>${right} / ${allKids.length} ${right===allKids.length?"✓ model ready for intervention":""}</b></div>
      <p class="note"><b>Top-down</b>: start from the objective and work down to factors (the diagram). <b>Bottom-up</b>: start from a measured fault and trace it up to the objective it affects. Each box must be fully determined by the boxes beneath it. Once every factor is listed, cross out the ones you cannot change — what remains is where an intervention can act.</p>`;
    el.querySelectorAll("[data-task]").forEach(b=>b.onclick=()=>{ hm.task=b.dataset.task; hm.crossed={}; renderHM(); }); el.querySelectorAll("rect[data-k]").forEach(r=>r.onclick=()=>{ hm.crossed[r.dataset.k]=!hm.crossed[r.dataset.k]; renderHM(); }); fixSubs(el); }

  /* ---------- 2. inverted U ---------- */
  let iu={x:0.5,fixed:false};
  function renderIU(){ const el=$("#invu"); const perf=(x)=>Math.max(0,1-Math.pow((x-0.6)/0.6,2)); const second=(x)=>Math.min(1,0.55+0.9*Math.min(x,0.5)); const P=(x)=>iu.fixed?perf(x):Math.min(perf(x),second(x));
    const X=(x)=>60+x*480, Y=(y)=>200-y*160; const pts=Array.from({length:81},(_,i)=>i/80);
    const plot=svg(600,240,ARROW+`<line x1="60" y1="200" x2="540" y2="200" stroke="#2c4274"/><line x1="60" y1="30" x2="60" y2="200" stroke="#2c4274"/><polyline points="${pts.map(x=>`${X(x)},${Y(perf(x))}`).join(" ")}" fill="none" stroke="#ff8a3d" stroke-width="2" stroke-dasharray="${iu.fixed?"":"5 4"}"/>${iu.fixed?"":`<polyline points="${pts.map(x=>`${X(x)},${Y(second(x))}`).join(" ")}" fill="none" stroke="#22d3ee" stroke-width="2" stroke-dasharray="5 4"/>`}<polyline points="${pts.map(x=>`${X(x)},${Y(P(x))}`).join(" ")}" fill="none" stroke="#7cff6b" stroke-width="3.5"/><circle cx="${X(iu.x)}" cy="${Y(P(iu.x))}" r="6" fill="#fff"/><line x1="${X(0.6)}" y1="30" x2="${X(0.6)}" y2="200" stroke="#ffd23f" stroke-dasharray="3 3"/>`+txt(X(0.6)+4,40,"optimal, not maximal",'style="fill:#ffd23f"')+txt(540,222,"the variable you are training (e.g. plantar-flexor strength) →",'text-anchor="end" class="mlab dim"')+txt(64,26,"performance",'class="mlab dim"')+(iu.fixed?"":txt(X(0.5)+6,Y(second(0.5))+16,"second limiting factor (e.g. hip ROM) caps the gain",'style="fill:#22d3ee"')));
    el.innerHTML=`<div class="ctl"><label>Training progress on the first variable <b>${f(iu.x*100,0)} %</b><input type="range" id="iux" min="0" max="1" step="0.01" value="${iu.x}"></label><label class="note"><input type="checkbox" id="iufix" ${iu.fixed?"checked":""}> fix the second limiting factor (now the first one can pay off)</label></div>${plot}
      <div class="ro"><span>Performance now</span><b>${f(P(iu.x)*100,0)} % of the achievable</b></div>
      <p><b>The inverted U.</b> More of a good thing is not always better: performance versus any one variable is nonlinear, with an <b>optimum</b> rather than a maximum. <b>Caution 1 — beyond optimal, no further gain.</b> Ten hot dogs with eight buns: the ninth sausage adds nothing. In gait, if hip range of motion limits step length, strengthening the plantar flexors will not help. <b>Caution 2 — do not stop at one limiting factor.</b> Add the sugar the cake was missing and the eggs become the shortfall. Fix the first limit, re-measure, find the next.</p>`;
    $("#iux").oninput=(e)=>{ iu.x=+e.target.value; renderIU(); }; $("#iufix").onchange=(e)=>{ iu.fixed=e.target.checked; renderIU(); }; fixSubs(el); }

  /* ---------- 3. standing balance ---------- */
  let bal={cop:0.02,cog:0.05,h:0.95,M:70,Tmax:110,foot:0.25,lat:false};
  function renderBal(){ const el=$("#balance"); const d=bal.cog-bal.cop; const W=bal.M*g; const Mnet=W*d; /* forward angular acceleration when COG ahead of COP */ const I=bal.M*bal.h*bal.h*1.33; const alpha=Mnet/I;
    const phiMax=deg(Math.asin(Math.min(1,bal.Tmax/(bal.M*g*bal.h)))); const phiBOS=deg(Math.atan((bal.foot*0.6)/bal.h)); const sway=deg(Math.atan(bal.cog/bal.h)); const limit=Math.min(phiMax,phiBOS);
    const strategy=!bal.lat?(d>0.005?["COG ahead of COP → body accelerates forward → <b>push-back</b>: plantar-flexor, knee flexor, hip extensor torques (COP moves anterior)","#ff5a5a"]:d<-0.005?["COP ahead of COG → body accelerates backward → <b>push-forward</b>: dorsiflexor, knee extensor, hip flexor torques","#22d3ee"]:["COP under COG → no angular acceleration — balanced","#7cff6b"]):(d>0.005?["COG lateral of COP → <b>subtalar eversion</b> torque, hip <b>abductors</b> on the stance side; knee contributes nothing","#ff5a5a"]:d<-0.005?["COG medial of COP → subtalar <b>inversion</b> torque, hip <b>adductors</b>","#22d3ee"]:["centred","#7cff6b"]);
    const S=240, gx=300, gy=250; const pend=svg(600,280,ARROW+`<rect x="${gx-bal.foot*0.4*S*3}" y="${gy}" width="${bal.foot*S*3}" height="10" fill="#6f86b3"/>`+txt(gx,275,`base of support ${f(bal.foot*100,0)} cm`,'text-anchor="middle" class="mlab dim"')
      +`<line x1="${gx}" y1="${gy}" x2="${gx+bal.cog*S*3}" y2="${gy-bal.h*S*0.9}" stroke="#e8e2d2" stroke-width="18" stroke-linecap="round"/><circle cx="${gx+bal.cog*S*3}" cy="${gy-bal.h*S*0.9}" r="16" fill="#ff8a3d"/>`+txt(gx+bal.cog*S*3+20,gy-bal.h*S*0.9+4,"COG",'style="fill:#ff8a3d"')
      +arrow(gx+bal.cog*S*3,gy-bal.h*S*0.9,gx+bal.cog*S*3,gy-bal.h*S*0.9+70,"#ffd23f",3)+txt(gx+bal.cog*S*3+8,gy-bal.h*S*0.9+68,"W",'style="fill:#ffd23f"')+arrow(gx+bal.cop*S*3,gy+6,gx+bal.cop*S*3,gy-80,"#7cff6b",4)+txt(gx+bal.cop*S*3+8,gy-70,"GRF at COP",'style="fill:#7cff6b"')
      +`<line x1="${gx+bal.cog*S*3}" y1="${gy-20}" x2="${gx+bal.cop*S*3}" y2="${gy-20}" stroke="#fff" stroke-width="2"/>`+txt((gx+bal.cog*S*3+gx+bal.cop*S*3)/2,gy-26,`d = ${f(d*100,1)} cm (horizontal scale ×3)`,'text-anchor="middle"')+(Math.abs(alpha)>0.01?`<path d="M${gx+bal.cog*S*3+(alpha>0?40:-40)},${gy-bal.h*S*0.9-30} a30,30 0 0 ${alpha>0?1:0} ${alpha>0?40:-40},30" fill="none" stroke="${strategy[1]}" stroke-width="4" marker-end="url(#${MK[strategy[1]]}@@)"/>`:""));
    el.innerHTML=`<div class="hierbar"><button type="button" class="tabbtn ${!bal.lat?"on":""}" data-lat="0">Anterior–posterior</button><button type="button" class="tabbtn ${bal.lat?"on":""}" data-lat="1">Medial–lateral</button></div>
      <div class="two"><div class="ctl"><label>COG position from the ankle (${bal.lat?"lateral":"anterior"} +) <b>${f(bal.cog*100,1)} cm</b><input type="range" data-k="cog" min="-0.1" max="0.18" step="0.005" value="${bal.cog}"></label><label>COP position (where you press the ground) <b>${f(bal.cop*100,1)} cm</b><input type="range" data-k="cop" min="-0.08" max="0.18" step="0.005" value="${bal.cop}"></label><label>Maximum ankle torque (plantar-flexor strength) <b>${bal.Tmax} N·m</b><input type="range" data-k="Tmax" min="20" max="250" step="5" value="${bal.Tmax}"></label><label>Body mass <b>${bal.M} kg</b> · COG height ${f(bal.h,2)} m<input type="range" data-k="M" min="45" max="120" step="1" value="${bal.M}"></label></div>${pend}</div>
      <div class="ro"><span>Gravitational moment about the ankle W·d</span><b>${f(Mnet,1)} N·m → angular acceleration ${f(alpha,2)} rad/s² ${alpha>0?"forward":alpha<0?"backward":""}</b></div>
      <div class="ro"><span>Strategy</span><b style="color:${strategy[1]}">${strategy[0]}</b></div>
      <div class="ro"><span>Current sway angle · strength limit (T_max = m g h sin φ) · geometric limit (COG over the toes)</span><b>${f(sway,1)}° · ${f(phiMax,1)}° · ${f(phiBOS,1)}° → limit of stability ${f(limit,1)}° (${phiMax<phiBOS?"strength-limited":"BOS-limited"})</b></div>
      <p><b>Balance is controlled by moving the COP relative to the COG.</b> COG ahead of COP: forward angular acceleration, corrected by the push-back strategy; COP ahead of COG: backward, corrected by push-forward. Side to side: subtalar inversion/eversion and hip ab/adductors — the knee contributes nothing in the frontal plane. The intervention target is to keep the COP under the COG and inside the base of support; the theoretical limit is the COG over the edge of the base, but a larger sway angle demands a larger ankle torque, so <b>stronger plantar flexors extend the limit of stability</b> up to the geometric edge.</p>`;
    el.querySelectorAll("[data-lat]").forEach(b=>b.onclick=()=>{ bal.lat=b.dataset.lat==="1"; renderBal(); }); el.querySelectorAll("input[data-k]").forEach(i=>i.oninput=()=>{ bal[i.dataset.k]=+i.value; renderBal(); }); fixSubs(el); }

  /* ---------- 4. jump & landing ---------- */
  let jp={shape:0.7,depth:0.35,rfd:0.6,M:75,land:0.5};
  function grf(t,o){ /* 0..1 propulsion time; U-shape (high performer) vs V-shape (low) blend; returns multiples of W above/below */ const u=Math.pow(Math.sin(Math.PI*t),0.5); const v=Math.pow(Math.sin(Math.PI*t),2.2); const base=o.shape*u+(1-o.shape)*v; const unweight=t<0.25?-0.5*Math.sin(Math.PI*t/0.25)*(o.depth/0.35):0; return 1+unweight+base*(1.3+0.8*o.rfd)*(t>0.2?1:t/0.2); }
  function renderJP(){ const el=$("#jump"); const W=jp.M*g; const Tp=0.45+0.5*jp.depth; const N=200; let J=0; const pts=[]; for(let i=0;i<=N;i++){ const t=i/N; const F=grf(t,jp); pts.push([t*Tp,F]); if(i) J+=((F-1)+(grf((i-1)/N,jp)-1))/2*W*(Tp/N); } const vto=Math.max(0,J/jp.M); const h=vto*vto/(2*g);
    const peak=Math.max(...pts.map(p=>p[1])); const X=(t)=>60+t/Tp*220, Y=(F)=>200-F/(peak*1.1)*160;
    const plot1=`<line x1="60" y1="200" x2="280" y2="200" stroke="#2c4274"/><line x1="60" y1="40" x2="60" y2="200" stroke="#2c4274"/><line x1="60" y1="${Y(1)}" x2="280" y2="${Y(1)}" stroke="#ffd23f" stroke-dasharray="4 4"/><polygon points="60,${Y(1)} ${pts.map(p=>`${X(p[0])},${Y(Math.max(p[1],1))}`).join(" ")} 280,${Y(1)}" fill="#7cff6b" fill-opacity=".2"/><polyline points="${pts.map(p=>`${X(p[0])},${Y(p[1])}`).join(" ")}" fill="none" stroke="#22d3ee" stroke-width="3"/>`+txt(64,36,`GRF · ${jp.shape>0.5?"U-shaped (high performer)":"V-shaped (low performer)"}`,'class="mlab dim"')+txt(170,222,"propulsion time →",'text-anchor="middle" class="mlab dim"')+txt(64,Y(1)-6,"W",'style="fill:#ffd23f"');
    /* landing */ const dz=0.05+0.45*jp.land; const Favg=jp.M*vto*vto/(2*dz)+W; const Fpk=Favg*1.6; const X2=(x)=>330+x*230; const plot2=`<line x1="330" y1="200" x2="560" y2="200" stroke="#2c4274"/><line x1="330" y1="40" x2="330" y2="200" stroke="#2c4274"/>${[0.1,0.3,0.5,0.7,0.9,1].map(l=>{ const d2=0.05+0.45*l; const Fp=(jp.M*vto*vto/(2*d2)+W)*1.6/W; return `<circle cx="${X2(l)}" cy="${200-Math.min(Fp,12)/12*160}" r="3" fill="#ff8a3d"/>`; }).join("")}<polyline points="${Array.from({length:41},(_,i)=>{ const l=0.05+0.95*i/40; const d2=0.05+0.45*l; const Fp=(jp.M*vto*vto/(2*d2)+W)*1.6/W; return `${X2(l)},${200-Math.min(Fp,12)/12*160}`; }).join(" ")}" fill="none" stroke="#ff8a3d" stroke-width="3"/><circle cx="${X2(jp.land)}" cy="${200-Math.min(Fpk/W,12)/12*160}" r="6" fill="#fff"/>`+txt(334,36,"peak landing GRF (× W) vs how much you flex",'class="mlab dim"')+txt(445,222,"stiff ← landing → soft",'text-anchor="middle" class="mlab dim"');
    el.innerHTML=`<div class="ctl"><label>Force–time shape: V (low) ↔ U (high performer) <b>${f(jp.shape,2)}</b><input type="range" data-k="shape" min="0" max="1" step="0.05" value="${jp.shape}"></label><label>Countermovement depth <b>${f(jp.depth*100,0)} cm</b><input type="range" data-k="depth" min="0.15" max="0.6" step="0.01" value="${jp.depth}"></label><label>Rate of force development <b>${f(jp.rfd,2)}</b><input type="range" data-k="rfd" min="0" max="1" step="0.05" value="${jp.rfd}"></label><label>Landing: stiff ↔ soft (COM lowering Δz = ${f(dz*100,0)} cm) <b>${f(jp.land,2)}</b><input type="range" data-k="land" min="0" max="1" step="0.05" value="${jp.land}"></label></div>
      ${svg(600,240,ARROW+plot1+plot2)}
      <div class="ro"><span>Net impulse (green area)</span><b>${f(J,0)} N·s</b></div><div class="ro"><span>Take-off velocity = J/m → jump height = v²/2g</span><b>${f(vto,2)} m/s → ${f(h*100,0)} cm</b></div><div class="ro"><span>Landing from that height: average force m v²/2Δz + W, peak ≈ 1.6× average</span><b>${f(Favg/W,1)} W avg · ${f(Fpk/W,1)} W peak</b></div>
      <p><b>Jump.</b> Objective: apex height. Correlate: take-off velocity (plus COM height at take-off). Models: impulse–momentum or work–energy, assuming zero velocity at the start of propulsion, constant mass and energy conserved in flight. Constraints: the COM must go straight up, take-off at full extension, knee angular velocity near zero at take-off (hyperextension risk). High performers show a <b>U-shaped</b> GRF — a larger impulse, not a higher peak — and faster force development. Pattern: flexion → extension → flexion; the countermovement adds the stretch reflex, elastic energy and a 'pre-forced' start higher on the force–time curve.</p>
      <p><b>Landing.</b> A stiff landing stops the COM in a short distance so the force is huge; a soft landing needs the strength and ROM to flex through a longer distance. Energy the MTCs do not absorb goes into other structures. Fatigue reduces flexion → less absorption → a coach substitutes before the injury happens. Interventions: mobility, strength (squats, deadlifts, lunges, calf raises), plyometrics (depth, vertical, broad jumps), technique, progressive overload, trunk control.</p>`;
    el.querySelectorAll("input[data-k]").forEach(i=>i.oninput=()=>{ jp[i.dataset.k]=+i.value; renderJP(); }); fixSubs(el); }

  /* ---------- 5. cycling ---------- */
  let cy={ang:60,locked:true,clips:false,playing:false};
  function renderCy(){ const el=$("#cycle"); const a=cy.ang; const phase=a<180?"Propulsion (TDC → BDC): hip and knee extending — an extension pattern":"Recovery (BDC → TDC): hip and knee flexing";
    const hipT=a<180?"extensor":"flexor", kneeT=a<180?"extensor":"flexor"; const ank=cy.locked?"plantar-flexors hold the ankle near neutral → shank energy reaches the pedal":"ankle unlocked → the pedal force drives the ankle into dorsiflexion: energy leaks";
    const cx=380, cyy=150, r=70; const pa=rad(a-90); const px=cx+r*Math.cos(pa), py=cyy+r*Math.sin(pa); /* hip fixed above-behind */ const hip=[200,40]; const L1=130,L2=130; const dx=px-hip[0], dy=py-hip[1]; const d=Math.hypot(dx,dy); const c2=Math.max(-1,Math.min(1,(d*d-L1*L1-L2*L2)/(2*L1*L2))); const q2=Math.acos(c2); const q1=Math.atan2(dy,dx)-Math.atan2(L2*Math.sin(q2),L1+L2*Math.cos(q2)); const kx=hip[0]+L1*Math.cos(q1), ky=hip[1]+L1*Math.sin(q1);
    const eff=a<180?Math.sin(rad(a))*(cy.locked?1:0.55):(cy.clips?-0.35*Math.sin(rad(a-180)):0);
    const pic=svg(600,300,ARROW+`<circle cx="${cx}" cy="${cyy}" r="${r}" fill="none" stroke="#2c4274" stroke-width="2"/><circle cx="${cx}" cy="${cyy}" r="8" fill="#6f86b3"/><line x1="${cx}" y1="${cyy}" x2="${px}" y2="${py}" stroke="#9fb3e6" stroke-width="6"/><rect x="${px-16}" y="${py-5}" width="32" height="10" rx="3" fill="#ffd23f"/>`
      +`<line x1="${hip[0]}" y1="${hip[1]}" x2="${kx}" y2="${ky}" stroke="#e8e2d2" stroke-width="16" stroke-linecap="round"/><line x1="${kx}" y1="${ky}" x2="${px}" y2="${py}" stroke="#cfc6b0" stroke-width="13" stroke-linecap="round"/><circle cx="${hip[0]}" cy="${hip[1]}" r="8" fill="#ff8a3d"/><circle cx="${kx}" cy="${ky}" r="7" fill="#22d3ee"/>`
      +txt(cx,cyy-r-10,"TDC",'text-anchor="middle" class="mlab dim"')+txt(cx,cyy+r+18,"BDC",'text-anchor="middle" class="mlab dim"')+(Math.abs(eff)>0.05?arrow(px,py,px+ (a<180?0:0),py+eff*70,"#7cff6b",4)+txt(px+20,py+eff*70,`pedal force ${f(Math.abs(eff)*100,0)} %`,'style="fill:#7cff6b"'):"")+txt(60,280,`crank angle ${a}° · ${phase.split(":")[0]}`,'class="mlab dim"'));
    el.innerHTML=`<div class="ctl"><label>Crank angle (0° = top dead centre) <b>${a}°</b><input type="range" data-k="ang" min="0" max="359" step="1" value="${a}"></label><div class="xray"><label class="note"><input type="checkbox" id="cylock" ${cy.locked?"checked":""}> ankle 'locked' by the plantar flexors</label><label class="note"><input type="checkbox" id="cyclips" ${cy.clips?"checked":""}> toe clips / clipless pedals</label><button type="button" class="btn small" id="cyplay">${cy.playing?"■ pause":"▶ pedal"}</button></div></div>${pic}
      <div class="ro"><span>Phase</span><b>${phase}</b></div><div class="ro"><span>Joint torques</span><b>hip ${hipT} · knee ${kneeT} · ankle ${a<180?"plantar-flexor (transfers shank energy to the pedal)":cy.clips?"dorsiflexor (pulling up)":"flexor moments but no energy to the pedal"}</b></div><div class="ro"><span>Ankle</span><b>${ank}</b></div>
      <p><b>Cycling.</b> Propulsion from TDC to BDC is an extension pattern at hip and knee; recovery is flexion. The ankle stays near neutral — but only if the plantar flexors 'lock' it, because the hip and knee cannot push on the pedal except through the ankle. Without that lock the pedal would drive the ankle into dorsiflexion and energy leaks. In recovery, clips let the flexors pull up; without clips flexor moments still occur but deliver nothing to the pedal. At the transitions the biarticular rectus femoris hands energy to the crank that single-joint muscles cannot. Intervention that follows: strengthen the plantar flexors.</p>`;
    $("#cylock").onchange=(e)=>{ cy.locked=e.target.checked; renderCy(); }; $("#cyclips").onchange=(e)=>{ cy.clips=e.target.checked; renderCy(); }; $("#cyplay").onclick=()=>{ cy.playing=!cy.playing; renderCy(); }; el.querySelectorAll("input[data-k]").forEach(i=>i.oninput=()=>{ cy[i.dataset.k]=+i.value; renderCy(); }); fixSubs(el); }
  setInterval(()=>{ if(cy.playing&&!$("#cycle").hidden){ cy.ang=(cy.ang+4)%360; renderCy(); } },60);

  /* ---------- 6. drinking from a glass ---------- */
  let gl={m:0.35,mu:0.4,grip:4,hgrip:0.5,elbow:120,trunk:0};
  function renderGl(){ const el=$("#glass"); const W=gl.m*g; const Nmin=W/(2*gl.mu); const ok=gl.grip>=Nmin; const safety=gl.grip/Nmin; /* reach: shoulder at origin, mouth at (0.15, 0.25) above; elbow ROM limit forces trunk flexion */ const L1=0.30,L2=0.28; const need=120; const deficit=Math.max(0,need-gl.elbow); const trunkNeeded=deficit*0.5;
    const pic=svg(600,240,ARROW+`<rect x="250" y="60" width="90" height="120" rx="6" fill="#9fd8ff" fill-opacity=".3" stroke="#9fd8ff"/><rect x="252" y="100" width="86" height="78" fill="#5fa8ff" fill-opacity=".35"/><circle cx="295" cy="${180-gl.hgrip*110}" r="4" fill="#ffd23f"/>`
      +arrow(190,180-gl.hgrip*110,246,180-gl.hgrip*110,"#ff8a3d",4)+arrow(400,180-gl.hgrip*110,344,180-gl.hgrip*110,"#ff8a3d",4)+txt(150,176-gl.hgrip*110,`N = ${f(gl.grip,1)} N`,'text-anchor="end" style="fill:#ff8a3d"')+arrow(250,180-gl.hgrip*110+10,250,180-gl.hgrip*110-40,"#7cff6b",3)+arrow(340,180-gl.hgrip*110+10,340,180-gl.hgrip*110-40,"#7cff6b",3)+txt(350,150-gl.hgrip*110,`friction ≤ μN each side`,'style="fill:#7cff6b"')+arrow(295,120,295,160,"#ffd23f",3)+txt(302,150,`W = ${f(W,2)} N`,'style="fill:#ffd23f"')+txt(295,215,ok?"holds — friction ≥ weight":"SLIPS — grip too light for this glass",`text-anchor="middle" style="fill:${ok?"#7cff6b":"#ff5a5a"}"`)+txt(295,232,`grip at ${f(gl.hgrip*100,0)} % height ${Math.abs(gl.hgrip-0.5)>0.3?"— far from the COM: the grip torque must balance a large tipping moment":"— near the COM: small tipping moment"}`,'text-anchor="middle" class="mlab dim"'));
    el.innerHTML=`<div class="two"><div class="ctl"><label>Glass + water mass <b>${f(gl.m*1000,0)} g</b><input type="range" data-k="m" min="0.1" max="0.8" step="0.01" value="${gl.m}"></label><label>Friction coefficient fingers–glass <b>${f(gl.mu,2)}</b> (dry 0.5, wet 0.2)<input type="range" data-k="mu" min="0.1" max="0.8" step="0.01" value="${gl.mu}"></label><label>Grip (normal) force per side <b>${f(gl.grip,1)} N</b><input type="range" data-k="grip" min="0.5" max="20" step="0.1" value="${gl.grip}"></label><label>Grip height on the glass <b>${f(gl.hgrip*100,0)} %</b><input type="range" data-k="hgrip" min="0.1" max="0.9" step="0.05" value="${gl.hgrip}"></label><label>Patient's available elbow flexion <b>${gl.elbow}°</b><input type="range" data-k="elbow" min="60" max="140" step="1" value="${gl.elbow}"></label></div>${pic}</div>
      <div class="ro"><span>Minimum grip to prevent slip: 2μN ≥ W → N ≥ W/(2μ)</span><b>${f(Nmin,2)} N per side · safety factor ${f(safety,2)}</b></div><div class="ro"><span>Transport to the mouth needs ≈ ${need}° of elbow flexion</span><b>${deficit>0?`${deficit}° short → compensate with ≈ ${f(trunkNeeded,0)}° of trunk flexion (bring the mouth to the glass)`:"reachable without compensation"}</b></div>
      <p><b>The task.</b> Objective: grasp the glass and bring it to the mouth; correlates: static force (friction must carry the weight) and static torque (the glass must not tip in the hand). Phases: reach &amp; grasp (extension pattern) → forward transport (flexion) → drink → backward transport (extension) → return. Holding the glass involves <b>11 forces and 10 torques</b> (taking moments about the COM removes gravity's torque). <b>Janice</b>, after a stroke, has reduced elbow ROM: she compensates with trunk flexion. Interventions: improve the impaired joint, build the capacity of the DOFs she substitutes with, or change the task — a lighter, narrower glass, or more friction.</p>`;
    el.querySelectorAll("input[data-k]").forEach(i=>i.oninput=()=>{ gl[i.dataset.k]=+i.value; renderGl(); }); fixSubs(el); }

  /* ---------- 7. wheelchair push ---------- */
  let wc={F:60,ang:20,rrim:0.27,rwheel:0.30,I:0.15,mtot:90};
  function renderWC(){ const el=$("#chair"); const Fperp=wc.F*Math.cos(rad(wc.ang)); const tau=Fperp*wc.rrim; const Ieff=wc.I+wc.mtot*wc.rwheel*wc.rwheel/2; /* two wheels share the chair+rider mass */ const alpha=tau/Ieff; const a=alpha*wc.rwheel;
    const cx=300, cyy=150, R=100, rr=R*wc.rrim/wc.rwheel; const ha=rad(-60); const hx=cx+rr*Math.cos(ha), hy=cyy+rr*Math.sin(ha); const tdir=ha+Math.PI/2; const fdir=tdir+rad(wc.ang);
    const pic=svg(600,300,ARROW+`<circle cx="${cx}" cy="${cyy}" r="${R}" fill="none" stroke="#9fb3e6" stroke-width="8"/><circle cx="${cx}" cy="${cyy}" r="${rr}" fill="none" stroke="#ffd23f" stroke-width="4"/><circle cx="${cx}" cy="${cyy}" r="6" fill="#6f86b3"/>`+arrow(hx,hy,hx+Math.cos(fdir)*70,hy+Math.sin(fdir)*70,"#ff8a3d",4)+txt(hx+Math.cos(fdir)*70+6,hy+Math.sin(fdir)*70,`hand force ${wc.F} N`,'style="fill:#ff8a3d"')+arrow(hx,hy,hx+Math.cos(tdir)*Fperp/wc.F*70,hy+Math.sin(tdir)*Fperp/wc.F*70,"#7cff6b",3)+txt(hx+Math.cos(tdir)*75-60,hy+Math.sin(tdir)*75-10,`tangential ${f(Fperp,0)} N`,'style="fill:#7cff6b"')+`<line x1="${cx}" y1="${cyy}" x2="${hx}" y2="${hy}" stroke="#ffd23f" stroke-dasharray="4 4"/>`+txt(cx+10,cyy+rr/2,"r_rim",'style="fill:#ffd23f"')+txt(cx+R+10,cyy,"r_wheel",'style="fill:#9fb3e6"')+txt(300,285,"only the component tangent to the rim makes torque",'text-anchor="middle" class="mlab dim"'));
    el.innerHTML=`<div class="two"><div class="ctl"><label>Hand force on the rim <b>${wc.F} N</b><input type="range" data-k="F" min="10" max="200" step="5" value="${wc.F}"></label><label>Angle of the push away from tangent <b>${wc.ang}°</b><input type="range" data-k="ang" min="0" max="80" step="1" value="${wc.ang}"></label><label>Hand-rim radius <b>${f(wc.rrim*100,0)} cm</b><input type="range" data-k="rrim" min="0.15" max="0.30" step="0.005" value="${wc.rrim}"></label><label>Wheel radius <b>${f(wc.rwheel*100,0)} cm</b><input type="range" data-k="rwheel" min="0.25" max="0.35" step="0.005" value="${wc.rwheel}"></label><label>Chair + rider mass <b>${wc.mtot} kg</b> · wheel I ${wc.I} kg·m²<input type="range" data-k="mtot" min="40" max="150" step="1" value="${wc.mtot}"></label></div>${pic}</div>
      <div class="ro"><span>Torque on the wheel τ = F_tangent · r_rim</span><b>${f(tau,2)} N·m</b></div><div class="ro"><span>Effective inertia per wheel I + (m/2) r_wheel²</span><b>${f(Ieff,2)} kg·m²</b></div><div class="ro"><span>Wheel angular acceleration α = τ / I_eff → chair acceleration a = α r_wheel</span><b>${f(alpha,2)} rad/s² → ${f(a,2)} m/s²</b></div>
      <p><b>Wheelchair propulsion.</b> Objective: accelerate the chair. Correlate: wheel angular acceleration, set by the hand force <i>perpendicular to the radius</i> (tangent to the rim), the hand-rim radius, and the wheel's effective inertia; the chair accelerates at α·r_wheel. Pushing radially inward wastes force; a larger rim gives more torque per newton but demands a longer, faster hand path. Users with limited shoulder ROM or strength trade rim size against stroke length — the same organismic-constraint reasoning as every other task.</p>`;
    el.querySelectorAll("input[data-k]").forEach(i=>i.oninput=()=>{ wc[i.dataset.k]=+i.value; renderWC(); }); fixSubs(el); }

  /* ---------- 8. gait viewer (synthetic) ---------- */
  let gt={mode:"walk",t:0.3};
  const G=(u,run)=>{ /* hip, knee, ankle angles (deg); ankle/knee/hip moments (N·m/kg); powers (W/kg) — synthetic textbook shapes */ const hip=run?(30*Math.cos(2*Math.PI*u)+10):(25*Math.cos(2*Math.PI*u)+5); const knee=run?(20+22*Math.exp(-Math.pow((u-0.2)/0.14,2))+70*Math.exp(-Math.pow((u-0.72)/0.1,2))):(12+10*Math.exp(-Math.pow((u-0.12)/0.08,2))+58*Math.exp(-Math.pow((u-0.73)/0.1,2))); const ank=run?(-5+18*Math.exp(-Math.pow((u-0.25)/0.14,2))-25*Math.exp(-Math.pow((u-0.42)/0.06,2))):(-5+10*Math.exp(-Math.pow((u-0.3)/0.15,2))-18*Math.exp(-Math.pow((u-0.58)/0.06,2)));
    const stance=run?0.4:0.62; const ma=u<stance?-(run?3.0:1.6)*Math.sin(Math.PI*Math.min(1,u/stance))*Math.pow(Math.min(1,u/stance),0.6):0; const mk=u<stance?(run?2.5:0.6)*Math.sin(Math.PI*u/stance)*Math.exp(-Math.pow((u-0.2*stance)/(0.5*stance),2))-(u<0.08?0.3*(1-u/0.08):0):-(u>0.85?0.3*(u-0.85)/0.15:0); const mh=u<stance?(run?2.0:1.0)*Math.cos(Math.PI*u/stance):0.2*Math.sin(2*Math.PI*(u-stance)/(1-stance));
    const pa=u<stance?(run?8:4)*Math.exp(-Math.pow((u-0.85*stance)/0.07,2))-(run?3:1)*Math.exp(-Math.pow((u-0.5*stance)/0.12,2)):0; const pk=u<stance?-(run?4:1.2)*Math.exp(-Math.pow((u-0.2*stance)/0.08,2))+(run?2:0.5)*Math.exp(-Math.pow((u-0.4*stance)/0.08,2)):-(1.0)*Math.exp(-Math.pow((u-0.92)/0.05,2)); const ph=(run?2:1)*Math.exp(-Math.pow((u-0.1)/0.08,2))+(run?1.5:0.8)*Math.exp(-Math.pow((u-stance-0.02)/0.07,2));
    return {hip,knee,ank,ma,mk,mh,pa,pk,ph,stance}; };
  const HAS_GAIT=(typeof GAIT!=="undefined");
  const GM=(u)=>{ const i=Math.max(0,Math.min(100,Math.round(u*100))); const a=GAIT.ang, m=GAIT.mom, p=GAIT.pwr; return {hip:a.hip[i],knee:a.knee[i],ank:a.ankle[i],mh:m.hip[i],mk:m.knee[i],ma:m.ank[i],ph:p.hip[i],pk:p.knee[i],pa:p.ank[i],stance:GAIT.events.toe_off/100}; };
  const gaitAt=(u)=>(gt.mode==="meas"&&HAS_GAIT)?GM(u):G(u,gt.mode==="run");
  function renderGait(){ const el=$("#gait"); const run=gt.mode==="run"; const meas=gt.mode==="meas"&&HAS_GAIT; const N=100;
    const rows=[["Joint angles (°) · flex/DF +",["hip","knee","ank"],["#ff8a3d","#22d3ee","#7cff6b"],-30,80],["Net joint moments (N·m/kg) · ext/PF +",["mh","mk","ma"],["#ff8a3d","#22d3ee","#7cff6b"],run?-3.5:-2,run?3.5:2],["Joint powers (W/kg) · gen +",["ph","pk","pa"],["#ff8a3d","#22d3ee","#7cff6b"],run?-5:-2,run?9:5]];
    const data=Array.from({length:N+1},(_,i)=>meas?GM(i/N):G(i/N,run)); const stance=data[0].stance; const cur=meas?GM(gt.t):G(gt.t,run);
    const panels=rows.map((r,ri)=>{ const y0=20+ri*95, hgt=70; const Y=(v)=>y0+hgt-(v-r[3])/(r[4]-r[3])*hgt; const X=(u)=>60+u*480; return `<rect x="60" y="${y0}" width="${480*stance}" height="${hgt}" fill="#ffd23f" fill-opacity=".06"/><line x1="60" y1="${Y(0)}" x2="540" y2="${Y(0)}" stroke="#2c4274"/>`+r[1].map((k,ki)=>`<polyline points="${data.map((d,i)=>`${X(i/N)},${Y(Math.max(r[3],Math.min(r[4],d[k])))}`).join(" ")}" fill="none" stroke="${r[2][ki]}" stroke-width="2"/>`).join("")+`<line x1="${X(gt.t)}" y1="${y0}" x2="${X(gt.t)}" y2="${y0+hgt}" stroke="#fff" opacity=".6"/>`+txt(62,y0+10,r[0],'class="mlab dim"'); }).join("");
    const ev=meas?`<line x1="${60+480*GAIT.events.opp_to/100-480}" y1="20" x2="${60+480*GAIT.events.opp_to/100-480}" y2="300" stroke="#9fb0d0" stroke-dasharray="3 3"/><line x1="${60+480*GAIT.events.opp_hs/100}" y1="20" x2="${60+480*GAIT.events.opp_hs/100}" y2="300" stroke="#9fb0d0" stroke-dasharray="3 3"/>`+txt(60+480*GAIT.events.opp_hs/100+3,300,"opp. heel strike",'class="mlab dim"'):"";
    const plot=svg(600,310,panels+ev+txt(60+480*stance/2,306,"stance",'text-anchor="middle" style="fill:#ffd23f"')+txt(60+480*(stance+(1-stance)/2),306,"swing",'text-anchor="middle" class="mlab dim"')+txt(540,14,"hip · knee · ankle",'text-anchor="end" class="mlab dim"'));
    let extra="";
    if(meas){ const Xg=(u)=>60+u*480; const Yg=(v)=>110-v*70; const gr=GAIT.grf; const line=(arr,c,w=2,dash="")=>`<polyline points="${arr.map((v,i)=>`${Xg(i/100)},${Yg(v)}`).join(" ")}" fill="none" stroke="${c}" stroke-width="${w}" ${dash?`stroke-dasharray="${dash}"`:""}/>`;
      const grfsvg=svg(600,130,`<rect x="60" y="${Yg(1.25)}" width="${480*stance}" height="${Yg(-0.25)-Yg(1.25)}" fill="#ffd23f" fill-opacity=".06"/><line x1="60" y1="${Yg(0)}" x2="540" y2="${Yg(0)}" stroke="#2c4274"/><line x1="60" y1="${Yg(1)}" x2="540" y2="${Yg(1)}" stroke="#2c4274" stroke-dasharray="2 4"/>`+txt(58,Yg(1)+4,"BW",'text-anchor="end" class="mlab dim"')+line(gr.vy_r,"#ffd23f")+line(gr.vx_r,"#ff8a3d")+line(gr.vy_l,"#9fb0d0",1.5,"4 3")+`<line x1="${Xg(gt.t)}" y1="${Yg(1.25)}" x2="${Xg(gt.t)}" y2="${Yg(-0.25)}" stroke="#fff" opacity=".6"/>`+txt(62,28,"Ground reaction force / BW · right vertical (yellow), right fore–aft (orange, + forward), left vertical (dashed)",'class="mlab dim"'));
      const keys=Object.keys(GAIT.emg); const rowH=22; const emgsvg=svg(600,20+keys.length*rowH,keys.map((k,r)=>{ const y0=16+r*rowH; const Ye=(v)=>y0+rowH-4-v*(rowH-6); return `<rect x="60" y="${y0}" width="${480*stance}" height="${rowH}" fill="#ffd23f" fill-opacity=".05"/>`+txt(56,y0+rowH-6,k,'text-anchor="end" class="mlab dim"')+`<polygon points="${Xg(0)},${Ye(0)} ${GAIT.emg[k].map((v,i)=>`${Xg(i/100)},${Ye(v)}`).join(" ")} ${Xg(1)},${Ye(0)}" fill="#b8413a" fill-opacity=".55" stroke="#ffb3a7" stroke-width="1"/>`; }).join("")+`<line x1="${Xg(gt.t)}" y1="12" x2="${Xg(gt.t)}" y2="${16+keys.length*rowH}" stroke="#fff" opacity=".6"/>`+txt(540,12,"surface EMG envelope (rectified, 6 Hz), each normalised to its peak",'text-anchor="end" class="mlab dim"'));
      const i=Math.round(gt.t*100); extra=`<h4 style="margin:10px 0 2px">Measured ground reaction forces</h4>${grfsvg}<div class="ro"><span>Now</span><b>right GRF ${f(gr.vy_r[i],2)} BW vertical, ${f(gr.vx_r[i],2)} BW fore–aft · left ${f(gr.vy_l[i],2)} BW</b></div>
        <h4 style="margin:10px 0 2px">Muscle activity (EMG) over the same stride</h4>${emgsvg}
        <p class="note">EMG channels: ${Object.entries(GAIT.emg_names).map(([k,v])=>`<b>${k}</b> ${v}`).join(" · ")}.</p>
        <p class="note"><b>Read the three plots together.</b> The plantar-flexor moment and ankle power burst (A2, ≈ 50–60 %) line up with the soleus and gastrocnemius envelopes and with the second GRF hump; the knee-extensor moment in early stance (K1) matches the vasti firing just after heel strike; tibialis anterior is active at heel strike (controlling foot slap) and again through swing (toe clearance); gluteus maximus and the hamstrings peak around heel strike, gluteus medius through single support. Where EMG timing leads the moment by a few tens of milliseconds, you are watching electromechanical delay and the force–velocity relation at work.</p>
        <p class="note">Trial: ${GAIT.source} Body weight ${GAIT.BW} N (${GAIT.mass} kg) from the GRF impulse; speed ${GAIT.speed} m/s; stride ${GAIT.T} s; toe-off ${GAIT.events.toe_off} %. ${GAIT.id_note} ${GAIT.credit}</p>`; }
    el.innerHTML=`<div class="hierbar"><button type="button" class="tabbtn ${gt.mode==="walk"?"on":""}" data-g="walk">Walking (textbook)</button><button type="button" class="tabbtn ${run?"on":""}" data-g="run">Running (textbook)</button>${HAS_GAIT?`<button type="button" class="tabbtn ${meas?"on":""}" data-g="meas">Measured walk · OpenSim data</button>`:""}<span class="note">${meas?"one real stride: markers, force plates and EMG":"synthetic textbook-shaped curves"}</span></div>
      <div class="ctl"><label>% of gait cycle (right heel strike = 0) <b>${f(gt.t*100,0)} %</b><input type="range" id="gtt" min="0" max="0.99" step="0.01" value="${gt.t}"></label></div>${plot}
      <div class="ro"><span>Now</span><b>hip ${f(cur.hip,0)}° · knee ${f(cur.knee,0)}° · ankle ${f(cur.ank,0)}° — moments ${f(cur.mh,2)} / ${f(cur.mk,2)} / ${f(cur.ma,2)} N·m/kg — powers ${f(cur.ph,1)} / ${f(cur.pk,1)} / ${f(cur.pa,1)} W/kg</b></div>${extra}
      <p><b>Walking has no single mechanical objective</b>, so the analysis leans on phases and critical elements: at heel strike the knee absorbs (K1), the hip extensors drive early stance (H1); the plantar-flexor moment grows through stance and the ankle delivers the big power burst at push-off (A2); the hip flexors pull the leg into swing (H3) and the hamstrings absorb at the end of swing (K4). <b>Running</b> shortens stance to ≈ 40 %, roughly doubles the ankle and knee moments and turns the knee into the main shock absorber; the body behaves like a bouncing spring–mass, exchanging elastic and kinetic energy, whereas walking exchanges potential and kinetic energy like an inverted pendulum (Farley &amp; Ferris 1998; Novacheck 1998). Soft tissues dissipate a surprising share of the collision energy at each step (Zelik &amp; Kuo 2010).</p>
      <p class="note"><b>Dysfunctional patterns.</b> <i>Valgus collapse</i>: knee drifts medially under load — excessive subtalar pronation and hip adduction/internal rotation; weak subtalar invertors and hip external rotators are the obvious causes, but ankle dorsiflexion loss, trunk lean and fatigue are the less obvious ones. <i>Lifting</i>: keep the load close to the spine (short external moment arm), avoid full lumbar flexion (ligaments and discs take the load the extensors should), and choose the lift — squat for heavy/compact loads, stoop for light/low ones, with the hip hinge as the default.</p>`;
    el.querySelectorAll("[data-g]").forEach(b=>b.onclick=()=>{ gt.mode=b.dataset.g; renderGait(); }); $("#gtt").oninput=(e)=>{ gt.t=+e.target.value; renderGait(); }; fixSubs(el); }

  /* ---------- 9. final review (cross-course) ---------- */
  const DR=(()=>{ const KEY="dpl-biomech-capstone"; let St={done:0,correct:0,streak:0,best:0}; try{ Object.assign(St,JSON.parse(localStorage.getItem(KEY))||{}); }catch(e){} const save=()=>{ try{ localStorage.setItem(KEY,JSON.stringify(St)); }catch(e){} };
    const Q=[
      /* framework */ ()=>({t:"Framework",q:"The four steps of a movement analysis, in order:",opts:shuffle(["objective → mechanical correlate → analyse the solution & identify faults → cause & intervention","intervention → objective → correlate → faults","faults → objective → correlate → intervention","correlate → objective → intervention → faults"]),ans:"objective → mechanical correlate → analyse the solution & identify faults → cause & intervention",why:"Step 4 goes beyond biomechanics."}),
      ()=>({t:"Framework",q:"'Proficiency' in a movement analysis refers to…",opts:shuffle(["how well the performer achieves the objective with their movement solution","how strong the performer is","the number of phases","the class of movement"]),ans:"how well the performer achieves the objective with their movement solution",why:"Judged against exemplary performance or guiding principles."}),
      ()=>({t:"Framework",q:"Organismic constraints include…",opts:shuffle(["ROM, strength, power and endurance of each degree of freedom","the playing surface","the rules of the task","the equipment"]),ans:"ROM, strength, power and endurance of each degree of freedom",why:"Environmental = extrinsic surroundings; task = goal and rules."}),
      ()=>({t:"Framework",q:"On the inverted U, training a variable past its optimum…",opts:shuffle(["gives no further gain — look for the next limiting factor","keeps improving performance linearly","always reduces injury risk","is impossible"]),ans:"gives no further gain — look for the next limiting factor",why:"Ten hot dogs, eight buns."}),
      ()=>({t:"Framework",q:"In a hierarchical model each box must be…",opts:shuffle(["fully determined by the boxes beneath it","larger than the box above","a muscle","measured with a force plate"]),ans:"fully determined by the boxes beneath it",why:"Objective at the top, correlates, then factors; cross out what you cannot change."}),
      /* balance */ ()=>({t:"Balance",q:"COG anterior to the COP produces…",opts:shuffle(["forward angular acceleration → push-back strategy (plantar flexors, knee flexors, hip extensors)","backward angular acceleration","no acceleration","lateral sway"]),ans:"forward angular acceleration → push-back strategy (plantar flexors, knee flexors, hip extensors)",why:"COP ahead of COG → backward → push-forward (dorsiflexors, knee extensors, hip flexors)."}),
      ()=>({t:"Balance",q:"In medial–lateral balance the knee…",opts:shuffle(["contributes no torque — subtalar and hip do the work","is the main controller","produces varus torque only","produces valgus torque only"]),ans:"contributes no torque — subtalar and hip do the work",why:"Subtalar inversion/eversion; hip abductors (lateral) and adductors (medial)."}),
      ()=>({t:"Balance",q:"Strengthening the plantar flexors improves standing balance by…",opts:shuffle(["raising the sway angle the ankle torque can recover from, toward the edge of the base of support","making the feet bigger","lowering the COG","reducing body mass"]),ans:"raising the sway angle the ankle torque can recover from, toward the edge of the base of support",why:"T = m g h sin φ: more torque, larger recoverable φ."}),
      /* jump/land */ ()=>({t:"Jump & land",q:"High-performing jumpers show a GRF–time curve that is…",opts:shuffle(["U-shaped — a larger impulse, not necessarily a higher peak","V-shaped with a sharp peak","flat","negative throughout"]),ans:"U-shaped — a larger impulse, not necessarily a higher peak",why:"Impulse, not peak force, sets take-off velocity."}),
      ()=>({t:"Jump & land",q:"Why is the knee angular velocity constrained to be near zero at take-off?",opts:shuffle(["to avoid knee hyperextension — gastrocnemius transfers thigh energy to the ankle instead","to reduce jump height","to keep the arms down","it is not constrained"]),ans:"to avoid knee hyperextension — gastrocnemius transfers thigh energy to the ankle instead",why:"Link-to-joint transfer at take-off."}),
      ()=>({t:"Jump & land",q:"A stiff landing compared with a soft one has…",opts:shuffle(["smaller COM displacement and much larger peak GRF","larger COM displacement and smaller GRF","the same GRF","no impact"]),ans:"smaller COM displacement and much larger peak GRF",why:"F ≈ m v²/2Δz + W: shorter stopping distance → bigger force."}),
      ()=>({t:"Jump & land",q:"Fatigue raises landing injury risk because…",opts:shuffle(["flexion decreases → less energy absorbed by muscle → more goes into ligaments and cartilage","the athlete jumps higher","GRF disappears","muscles get stiffer and absorb more"]),ans:"flexion decreases → less energy absorbed by muscle → more goes into ligaments and cartilage",why:"Energy not absorbed by MTCs goes to other structures — substitute before the injury."}),
      ()=>({t:"Jump & land",q:"The long jump is best described as…",opts:shuffle(["a vertical jump rotated before extension","a pure horizontal push","a swing pattern","a cyclic skill"]),ans:"a vertical jump rotated before extension",why:"Range depends on v² sin 2θ — velocity dominates."}),
      /* cycling */ ()=>({t:"Cycling",q:"Why must the ankle be 'locked' by the plantar flexors in the power phase?",opts:shuffle(["so hip and knee extensor energy can reach the pedal instead of driving the ankle into dorsiflexion","to keep the heel down for style","to allow the toe clips to work","it should be relaxed"]),ans:"so hip and knee extensor energy can reach the pedal instead of driving the ankle into dorsiflexion",why:"Hence: strengthen the plantar flexors to improve cycling."}),
      ()=>({t:"Cycling",q:"At the pedal-cycle transitions, which muscle delivers energy to the crank that single-joint muscles cannot?",opts:shuffle(["rectus femoris (biarticular)","soleus","vastus medialis","gluteus maximus"]),ans:"rectus femoris (biarticular)",why:"Joint-to-joint transfer across hip and knee."}),
      /* glass */ ()=>({t:"Reaching",q:"The mechanical correlates for drinking from a glass are…",opts:shuffle(["static force (friction ≥ weight) and static torque (no tipping)","take-off velocity","angular momentum","impulse"]),ans:"static force (friction ≥ weight) and static torque (no tipping)",why:"Constraints: the glass may neither slip nor tip."}),
      ()=>({t:"Reaching",q:"Holding an object involves how many forces and torques in the class free-body analysis?",opts:shuffle(["11 forces, 10 torques (moments about the COM so gravity's torque vanishes)","3 forces, 3 torques","1 force, 1 torque","11 forces, 11 torques"]),ans:"11 forces, 10 torques (moments about the COM so gravity's torque vanishes)",why:"Taking moments about the COM removes gravity from the torque count."}),
      ()=>({t:"Reaching",q:"Janice's reduced elbow ROM after a stroke is compensated by…",opts:shuffle(["trunk flexion bringing the mouth toward the glass","a longer forearm","jumping","shoulder extension"]),ans:"trunk flexion bringing the mouth toward the glass",why:"Intervene on the impairment, on the substituting DOFs, or on the task (lighter, smaller glass)."}),
      /* wheelchair */ ()=>({t:"Wheelchair",q:"The hand force that produces torque on a wheelchair rim is the component…",opts:shuffle(["tangent to the rim (perpendicular to the radius)","directed into the hub","vertical","along the arm"]),ans:"tangent to the rim (perpendicular to the radius)",why:"τ = F⊥ r_rim; α = τ/I; a = α r_wheel."}),
      /* gait */ ()=>({t:"Gait",q:"Walking is hard to analyse because…",opts:shuffle(["it has no clear single mechanical objective — a hierarchical model is needed","it is too fast","it has no phases","it uses no muscles"]),ans:"it has no clear single mechanical objective — a hierarchical model is needed",why:"Speed, economy and stability all matter."}),
      ()=>({t:"Gait",q:"Walking vs running energetics:",opts:shuffle(["walking exchanges potential and kinetic energy (inverted pendulum); running stores and returns elastic energy (spring–mass)","both are inverted pendulums","both are pure springs","neither exchanges energy"]),ans:"walking exchanges potential and kinetic energy (inverted pendulum); running stores and returns elastic energy (spring–mass)",why:"Farley & Ferris 1998."}),
      ()=>({t:"Gait",q:"Valgus collapse of the knee is associated with…",opts:shuffle(["excessive subtalar pronation and hip adduction/internal rotation; weak invertors and hip external rotators","strong hip abductors","a varus knee","toe-walking"]),ans:"excessive subtalar pronation and hip adduction/internal rotation; weak invertors and hip external rotators",why:"Less obvious causes: limited dorsiflexion, trunk lean, fatigue."}),
      ()=>({t:"Gait",q:"Safe lifting mechanics emphasise…",opts:shuffle(["keeping the load close to the spine and avoiding full lumbar flexion","a long reach with straight legs","maximal lumbar flexion","lifting fast"]),ans:"keeping the load close to the spine and avoiding full lumbar flexion",why:"Short external moment arm; let the extensors, not the ligaments, carry it."}),
      /* cross-course */ ()=>({t:"Review · frames",q:"Sagittal-plane movements rotate about which ISB axis?",opts:shuffle(["Z (medial–lateral)","X (anterior–posterior)","Y (longitudinal)","none"]),ans:"Z (medial–lateral)",why:"Frontal plane about X; transverse about Y."}),
      ()=>({t:"Review · muscle",q:"PCSA = V / L_f; muscle force ≈ 30 N/cm² × PCSA × …",opts:shuffle(["cos α (pennation) to get the tendon force","sin α","tan α","nothing — pennation is irrelevant"]),ans:"cos α (pennation) to get the tendon force",why:"Architecture trades force for excursion."}),
      ()=>({t:"Review · arthro",q:"Convex-on-concave: roll and glide are…",opts:shuffle(["opposite","the same direction","perpendicular","unrelated"]),ans:"opposite",why:"Concave-on-convex: same direction."}),
      ()=>({t:"Review · kinetics",q:"EMA = r_muscle / r_external is usually…",opts:shuffle(["< 1: muscle force exceeds the load and the joint carries both","> 1","exactly 1","negative"]),ans:"< 1: muscle force exceeds the load and the joint carries both",why:"Only skill and hypertrophy improve the situation."}),
      ()=>({t:"Review · inverse dynamics",q:"Inverse dynamics proceeds…",opts:shuffle(["from the segment on the force plate toward the trunk, passing −R and −M across each joint","from the head down","from the trunk outward","in any order"]),ans:"from the segment on the force plate toward the trunk, passing −R and −M across each joint",why:"Only the foot has a fully known external force."}),
      ()=>({t:"Review · tissue",q:"Holding a calf stretch at constant length while the tension fades is…",opts:shuffle(["stress relaxation","creep","hysteresis","yield"]),ans:"stress relaxation",why:"Constant force → increasing length is creep (bracing)."}),
      ()=>({t:"Review · MTC",q:"At a fixed MTC length, raising activation makes the fibres…",opts:shuffle(["shorten while the tendon lengthens","lengthen","stay fixed","detach"]),ans:"shorten while the tendon lengthens",why:"Same force in series; the tendon is the spring."}),
      ()=>({t:"Review · multi-joint",q:"A whip pattern has segments rotating…",opts:shuffle(["the same way, for maximal endpoint velocity","opposite ways, for a straight path","not at all","about different planes"]),ans:"the same way, for maximal endpoint velocity",why:"Flexion/extension patterns: opposite rotation, straight line, force/accuracy."}),
      ()=>({t:"Review · energy",q:"Gastrocnemius slowing the thigh and delivering that energy to the ankle at take-off is…",opts:shuffle(["link-to-joint transfer","joint-to-link transfer","link-to-link transfer","no transfer"]),ans:"link-to-joint transfer",why:"Also prevents knee hyperextension."}),
      ()=>({t:"Review · stability",q:"Activating muscles around a joint…",opts:shuffle(["raises compression and friction capacity, opposing the perturbation, at the cost of joint load","reduces joint compression","has no effect","only matters at rest"]),ans:"raises compression and friction capacity, opposing the perturbation, at the cost of joint load",why:"μ(N + F_m)."}),
      ()=>({t:"Review · anthropometry",q:"Dempster's thigh mass fraction and COM location are about…",opts:shuffle(["0.100 M; 0.433 L from the hip","0.0465 M; 0.5 L","0.0145 M; 0.5 L","0.2 M; 0.25 L"]),ans:"0.100 M; 0.433 L from the hip",why:"Shank 0.0465, foot 0.0145."})];
    let cur=null; function next(){ cur=pick(Q)(); const el=$("#cdrill"); el.innerHTML=`<div class="jmeta"><span class="chip">${cur.t}</span></div><div class="dq">${cur.q}</div><div class="dopts">${cur.opts.map(o=>`<button type="button" class="btn dopt" data-o="${o.replace(/"/g,"&quot;")}">${o}</button>`).join("")}</div><div class="dfb" id="cdfb"></div><div class="dstat">Answered ${St.done} · correct ${St.correct} · streak ${St.streak} (best ${St.best})</div>`; el.querySelectorAll(".dopt").forEach(b=>b.onclick=()=>answer(b.dataset.o,b)); fixSubs(el); }
    function answer(o,b){ const ok=o===cur.ans; St.done++; if(ok){ St.correct++; St.streak++; St.best=Math.max(St.best,St.streak); } else St.streak=0; save(); $("#cdrill").querySelectorAll(".dopt").forEach(x=>{ x.disabled=true; if(x.dataset.o===cur.ans) x.classList.add("good"); else if(x===b&&!ok) x.classList.add("bad"); }); $("#cdfb").innerHTML=`<p class="${ok?"fb good":"fb bad"}">${ok?"Correct.":"Not quite — the answer is <b>"+cur.ans+"</b>."} ${cur.why}</p><button type="button" class="btn primary small" id="cnext">Next question →</button>`; $("#cnext").onclick=next; const ds=$("#cdrill .dstat"); if(ds) ds.textContent=`Answered ${St.done} · correct ${St.correct} · streak ${St.streak} (best ${St.best})`; if(typeof GAME!=="undefined"&&ok) GAME.addXP(10,St.streak>1?`+10 XP · ${St.streak} in a row`:"+10 XP"); }
    return {next}; })();

  function init(){ renderHM(); renderIU(); renderBal(); renderJP(); renderCy(); renderGl(); renderWC(); renderGait();
    document.querySelectorAll("#mtabs .tabbtn").forEach(b=>b.onclick=()=>{ document.querySelectorAll("#mtabs .tabbtn").forEach(x=>x.classList.toggle("on",x===b)); document.querySelectorAll(".mpane").forEach(p=>p.hidden=p.id!==b.dataset.k); });
    $("#cdrillstart").onclick=()=>{ DR.next(); $("#cdrillstart").textContent="Skip →"; }; }
  return {init,G,gaitAt,get:()=>({hm,iu,bal,jp,cy,gl,wc,gt})};
})();
CP.init();
